from __future__ import annotations

from dataclasses import dataclass
from typing import Any

from mage_agent.core.config import AgentConfig, save_config
from mage_agent.core.errors import ConfigError
from mage_agent.core.http import MageApiClient
from mage_agent.core.workspaces import (context_kind_for_project_type,
                                        derive_management_cluster_url,
                                        derive_workspace_cluster_url,
                                        extract_workspace_name,
                                        is_standalone_project,
                                        is_workspace_management,
                                        is_workspace_project,
                                        parse_status_response,
                                        project_type_from_status)


def _workspace_record(raw: Any) -> dict[str, Any] | None:
    if not isinstance(raw, dict):
        return None
    workspace = raw.get("workspace")
    payload = workspace if isinstance(workspace, dict) else raw
    name = payload.get("name")
    if not isinstance(name, str) or not name.strip():
        return None
    record: dict[str, Any] = {"name": name.strip()}
    for key in ("url", "repo_path", "cluster_type", "status", "project_uuid"):
        value = payload.get(key)
        if value is not None:
            record[key] = value
    instance = raw.get("instance") if isinstance(raw.get("instance"), dict) else None
    if instance:
        for key in ("status", "ip", "type"):
            value = instance.get(key)
            if value is not None:
                record.setdefault("instance", {})[key] = value
        if "status" in instance and "status" not in record:
            record["status"] = instance.get("status")
    return record


def _unwrap_workspaces(response: Any) -> list[Any]:
    if isinstance(response, list):
        return response
    if not isinstance(response, dict):
        return []
    if isinstance(response.get("raw"), str):
        return []
    for key in ("workspaces", "workspace"):
        value = response.get(key)
        if isinstance(value, list):
            return value
    return []


@dataclass
class WorkspaceTools:
    config: AgentConfig

    def _fetch_status(self, base_url: str | None = None) -> dict[str, Any] | None:
        api = MageApiClient(self.config, base_url=base_url)
        return parse_status_response(api.get("/api/status"))

    def _current_status(self) -> dict[str, Any] | None:
        if not self.config.cluster_url:
            return None
        return self._fetch_status(self.config.cluster_url)

    def management_cluster_url(self, status: dict[str, Any] | None = None) -> str:
        """
        API base for workspace management (``GET /api/workspaces``).

        Uses ``management_cluster_url`` from config when set; otherwise derives from
        ``cluster_url`` (strips workspace segment when ``project_type`` is ``sub``).
        """
        cluster_url = self.config.cluster_url
        if not cluster_url:
            raise ConfigError("Missing `cluster_url` in config.")

        project_type = project_type_from_status(status)
        if is_workspace_management(project_type):
            return cluster_url.rstrip("/")

        stored = (self.config.management_cluster_url or "").strip()
        if stored:
            return stored.rstrip("/")

        return derive_management_cluster_url(cluster_url)

    def active_context(self, status: dict[str, Any] | None = None) -> dict[str, Any]:
        if status is None:
            status = self._current_status()

        cluster_url = self.config.cluster_url
        project_type = project_type_from_status(status)

        workspace_name = self.config.workspace_name
        if is_workspace_project(project_type) and not workspace_name and cluster_url:
            workspace_name = extract_workspace_name(cluster_url)

        context: dict[str, Any] = {
            "workspace_name": workspace_name,
            "cluster_url": cluster_url,
            "management_cluster_url": self.management_cluster_url(status),
            "project_type": project_type,
            "context_kind": context_kind_for_project_type(project_type),
        }
        if status:
            for key in (
                "repo_path",
                "repo_path_root",
                "project_uuid",
                "instance_type",
                "is_instance_manager",
            ):
                if status.get(key) is not None:
                    context[key] = status.get(key)
        return context

    def list_workspaces(self) -> dict[str, Any]:
        status = self._current_status()
        active = self.active_context(status)
        project_type = active.get("project_type")

        if is_standalone_project(project_type):
            return {
                "workspaces": [],
                "active": active,
                "message": (
                    "Standalone Mage project (project_type=standalone). "
                    "Workspace listing is only available on workspace management "
                    "(project_type=main)."
                ),
            }

        management_url = active["management_cluster_url"]
        api = MageApiClient(self.config, base_url=management_url)
        response = api.get("/api/workspaces")
        records = []
        for item in _unwrap_workspaces(response):
            record = _workspace_record(item)
            if record:
                records.append(record)

        result: dict[str, Any] = {
            "workspaces": records,
            "active": active,
            "list_api_base": management_url,
        }
        if not records and isinstance(response, dict) and isinstance(response.get("raw"), str):
            result["message"] = (
                "Workspace list returned a non-JSON response. "
                "Confirm cluster_url points at the management API "
                "(project_type=main from GET /api/status), not the /manage UI path."
            )
        return result

    def switch_workspace(self, workspace_name: str) -> dict[str, Any]:
        name = (workspace_name or "").strip()
        if not name:
            raise ConfigError("workspace_name is required.")

        status = self._current_status()
        if is_standalone_project(project_type_from_status(status)):
            raise ConfigError(
                "Cannot switch workspaces on a standalone Mage project "
                "(project_type=standalone)."
            )

        management_url = self.management_cluster_url(status)
        new_cluster_url = derive_workspace_cluster_url(
            management_url,
            name,
            reference_cluster_url=self.config.cluster_url,
        )

        updated = AgentConfig(
            cluster_url=new_cluster_url,
            api_key=self.config.api_key,
            oauth_token=self.config.oauth_token,
            management_cluster_url=management_url,
            workspace_name=name,
        )

        switched_status = self._fetch_status(new_cluster_url)
        switched_type = project_type_from_status(switched_status)
        if not is_workspace_project(switched_type):
            raise ConfigError(
                f"Workspace switch failed: GET /api/status at `{new_cluster_url}` "
                f"did not return project_type=sub (got {switched_type!r}). "
                "Check the workspace name and that the instance is running."
            )

        path = save_config(updated)
        self.config = updated

        return {
            "workspace_name": name,
            "cluster_url": new_cluster_url,
            "management_cluster_url": management_url,
            "config_path": str(path),
            "project_type": switched_type,
            "context_kind": context_kind_for_project_type(switched_type),
        }
